fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "N/A"

    val halfSecondNs = 500_000_000L
    return if (exposureTimeNs < halfSecondNs) {
        val denominator = (1_000_000_000L / exposureTimeNs.toDouble()).roundToInt()
        "1/${denominator.coerceAtLeast(1)}s"
    } else {
        val seconds = exposureTimeNs / 1_000_000_000.0
        val whole = seconds.toLong()
        if (kotlin.math.abs(seconds - whole) < 1e-6) {
            "${whole}s"
        } else {
            "${String.format("%.1f", seconds)}s"
        }
    }
}

