import sys

path = '/home/agent/workspace/source.kt'
with open(path, encoding='utf-8') as f:
    src = f.read()

ends_with_nl = src.endswith('\n')
lines = src.split('\n')


def process_line(line):
    in_str = False
    in_char = False
    escape = False
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if in_str:
            if escape:
                escape = False
            elif c == '\\':
                escape = True
            elif c == '"':
                in_str = False
            i += 1
        elif in_char:
            if escape:
                escape = False
            elif c == '\\':
                escape = True
            elif c == "'":
                in_char = False
            i += 1
        else:
            if c == '"':
                in_str = True
            elif c == "'":
                in_char = True
            elif c == '/' and i + 1 < n and line[i + 1] == '/':
                before = line[:i]
                if before.strip() == '':
                    return None  # whole line is a comment -> drop it
                return before.rstrip()  # trailing comment -> keep code, strip comment
            else:
                i += 1
    return line  # no comment found


out = []
removed = 0
for line in lines:
    r = process_line(line)
    if r is None:
        removed += 1
        continue
    out.append(r)

result = '\n'.join(out)
if ends_with_nl:
    result += '\n'

with open(path, 'w', encoding='utf-8') as f:
    f.write(result)

print(f"Removed {removed} comment-only lines.")

