            if k == "P":
                s = 1 if white else -1
                sr = 1 if white else 6
                last = 7 if white else 0
                if 0 <= r + s < 8 and grid[r + s][f] is None:
                    if r + s == last:
                        for pr in "qrbn":
                            moves.append((r, f, r + s, f, pr))
                    else:
