                        if r == sr and grid[r + 2 * s][f] is None:
                            moves.append((r, f, r + 2 * s, f, None))
                for df in (-1, 1):
                    nf = f + df
                    if 0 <= nf < 8 and 0 <= r + s < 8:
                        t = grid[r + s][nf]
