            elif k == "K":
                for dr, df in KG:
                    r2, f2 = r + dr, f + df
                    if 0 <= r2 < 8 and 0 <= f2 < 8 and (grid[r2][f2] is None or grid[r2][f2].isupper() != white):
                        moves.append((r, f, r2, f2, None))
            else:
                for dr, df, kinds in RAYS:
                    if k not in kinds:
