def apply(grid, stm, cast, ep, mv):
    r, f, r2, f2, promo = mv
    white = stm == "w"
    orig_to = grid[r2][f2]
    p = grid[r][f]
    g = [row[:] for row in grid]
    g[r2][f2] = (promo.upper() if white else promo) if promo else p
    g[r][f] = None
    is_ep = p in ("P", "p") and ep != "-" and orig_to is None \
        and r2 == int(ep[1]) - 1 and f2 == FILES.index(ep[0])
