        chars = set(new_cast)
        if p == "K": chars.difference_update("KQ")
        elif p == "k": chars.difference_update("kq")
        for (sr, sf), right in CORNERS:
            if (r, f) == (sr, sf) or (r2, f2) == (sr, sf):
                chars.discard(right)
        new_cast = "".join(c for c in "KQkq" if c in chars) or "-"
    return g, ("b" if white else "w"), new_cast, new_ep

def ref_legal(fen):
    grid, stm, cast, ep = parse(fen)
    white = stm == "w"
    return [mv for mv in gen(grid, stm, cast, ep)
            if not in_check(apply(grid, stm, cast, ep, mv)[0], white)]

def ref_perft(fen, depth):
    if depth == 0:
        return 1
    grid, stm, cast, ep = parse(fen)
    total = 0
    for mv in ref_legal(fen):
        g2, s2, c2, e2 = apply(grid, stm, cast, ep, mv)
        total += ref_perft(" ".join([placement(g2), s2, c2, e2]), depth - 1)
    return total

